"use client";

import React, { useState } from "react";
import { Heart } from "lucide-react";
import { notification } from "antd";

import { doc, getDoc } from "firebase/firestore";

import { db } from "@/components/lib/firebase";
import { useAuth } from "@/context/AuthContext";
import { useModal } from "@/context/ModalContext";

export const GameCard = ({
  title,
  image,
  provider,
}) => {
  const { user } = useAuth();
  const { openModal } = useModal();

 const handleAction = (modalType) => {
  openModal(modalType);
};

  const [api, contextHolder] =
    notification.useNotification();

  const [loading, setLoading] =
    useState(false);

  const handleGameClick = async () => {
  if (!user?.uid) {
    api.warning({
      message: "Login Required",
      description: "গেম খেলতে প্রথমে লগইন করুন।",
      placement: "topRight",
    });

    // Open Login Modal
    openModal("login");

    return;
  }

  setLoading(true);

  try {
    const balanceRef = doc(
      db,
      "balance",
      user.uid
    );

    const balanceSnap = await getDoc(balanceRef);

    if (!balanceSnap.exists()) {
      api.warning({
        message: "Insufficient Balance",
        description:
          "আপনার ব্যালেন্স ৳100 এর কম। প্রথমে ডিপোজিট করুন।",
        placement: "topRight",
      });

      // Open Deposit Modal
      openModal("ডিপোজিট");

      return;
    }

    const balanceData = balanceSnap.data();

    const balanceAmount = Number(
      balanceData?.amount || 0
    );

    console.log("User Balance:", balanceAmount);

    if (balanceAmount < 100) {
      api.warning({
        message: "Insufficient Balance",
        description:
          "গেম খেলতে আপনার ব্যালেন্সে কমপক্ষে ৳100 থাকতে হবে।",
        placement: "topRight",
      });

      // Open Deposit Modal
      openModal("ডিপোজিট");

      return;
    }

    api.error({
      message: "Server Not Responding",
      description:
        "Server not responding. Please try again later.",
      placement: "topRight",
    });

  } catch (error) {
    console.error("Balance check error:", error);

    api.error({
      message: "Something Went Wrong",
      description:
        "Unable to check your balance. Please try again.",
      placement: "topRight",
    });

  } finally {
    setLoading(false);
  }
};


  return (
    <>
      {contextHolder}

      <div className="relative group cursor-pointer">
        <div className="aspect-[3/4] overflow-hidden relative rounded-xl border border-white/10 shadow-lg bg-slate-900">
          {provider && (

            <div className="absolute top-0 left-0 z-20">

              <div className="bg-white text-black text-[10px] font-black px-2 py-0.5 rounded-br-lg shadow-md uppercase">

                {provider}

              </div>

              <div className="w-0 h-0 border-t-[6px] border-t-white border-r-[6px] border-r-transparent" />

            </div>

          )}

          <button
            type="button"
            className="
              absolute
              top-2
              right-2
              z-20
              bg-black/30
              backdrop-blur-sm
              p-1.5
              rounded-full
              hover:bg-black/50
              transition
            "
          >

            <Heart className="w-4 h-4 text-white fill-white/20" />

          </button>


          {/* ============================= */}
          {/* MAIN GAME IMAGE */}
          {/* ============================= */}

          <img
            src={
              typeof image === "string"
                ? image
                : image?.src
            }
            alt={title}
            className="
              w-full
              h-full
              object-cover
              transition-transform
              duration-500
              group-hover:scale-110
            "
          />


          {/* ============================= */}
          {/* HOVER OVERLAY */}
          {/* ============================= */}

          <div
            className="
              absolute
              inset-0
              bg-black/60
              flex
              flex-col
              items-center
              justify-center
              gap-3
              opacity-0
              group-hover:opacity-100
              transition-opacity
              duration-300
              z-10
              p-4
            "
          >


            {/* ============================= */}
            {/* PLAY NOW BUTTON */}
            {/* ============================= */}

            <button
              type="button"
              disabled={loading}
              onClick={() =>
                handleGameClick("play")
              }
              className="
                w-full
                py-2
                bg-gradient-to-b
                from-yellow-300
                to-yellow-500
                hover:from-yellow-200
                hover:to-yellow-400
                disabled:opacity-60
                disabled:cursor-not-allowed
                text-red-800
                font-bold
                rounded-lg
                shadow-[0_4px_0_rgb(153,101,21)]
                active:translate-y-1
                active:shadow-none
                transition-all
                text-sm
              "
            >

              {loading
                ? "Checking..."
                : "এখন খেলুন"}

            </button>


            {/* ============================= */}
            {/* FREE TRIAL BUTTON */}
            {/* ============================= */}

            {/* <button
              type="button"
              disabled={loading}
              onClick={() =>
                handleGameClick("trial")
              }
              className="
                w-full
                py-2
                bg-gradient-to-b
                from-amber-400
                to-amber-600
                hover:from-amber-300
                hover:to-amber-500
                disabled:opacity-60
                disabled:cursor-not-allowed
                text-red-900
                font-bold
                rounded-lg
                shadow-[0_4px_0_rgb(120,70,10)]
                active:translate-y-1
                active:shadow-none
                transition-all
                text-sm
              "
            >

              {loading
                ? "Checking..."
                : "ফ্রি ট্রায়াল"}

            </button> */}



            {/* ============================= */}
            {/* GAME TITLE */}
            {/* ============================= */}

            <p className="
              text-white
              font-bold
              text-sm
              mt-2
              drop-shadow-md
              text-center
            ">

              {title}

            </p>

          </div>


          {/* ============================= */}
          {/* BOTTOM TITLE */}
          {/* ============================= */}

          <div
            className="
              absolute
              bottom-0
              left-0
              right-0
              bg-gradient-to-t
              from-black/90
              to-transparent
              pt-8
              pb-3
              px-2
              group-hover:opacity-0
              transition-opacity
            "
          >

            <p className="
              text-white
              text-[13px]
              font-black
              text-center
              uppercase
              tracking-wider
              drop-shadow-lg
            ">

              {title}

            </p>

          </div>

        </div>

      </div>
    </>
  );
};